@js:
const hashMatch = result.match(/parseInt\|([a-f0-9]+)\|player/);
const hash = hashMatch[1];
const ts = Math.floor(Date.now() / 1000 / 2000);

const jsUrl = source.getKey() + 'player/' + hash + '/' + ts + '.js?v=1';
const js = java.ajax(jsUrl);
const nxvav = "https://api.nxvav.cn/api/m3u8/?url=";
let m3u8 = "";

this.navigator = {
    userAgent: ""
};
const ad_config = "";
let videoId = "";
let auth_key = "";
let last_play_time = 0;
let volume = 0;
let autoplay = false;
let autoplayMuted = false;
let showIcon = false;
let preferDocument = false;
let pip = {};
let videoAttributes = {};
let advertise = {};
let manual_duration = 0;
let play_duration = 0;
let muted = false;
let video = {};
let external = false;
let disabled = false;
let key = "";
let time = {};
let duration = 0;

function create_player(a) {
    m3u8 = a["url"];
    // java.log(m3u8);
}

try {
    eval(String(js));
    if (m3u8 === "") {
        "未获取到视频地址"
    } else {
        java.startBrowserAwait(`${nxvav}${java.encodeURI(m3u8)}`, book.name);
    }
} catch (err) {
    if (m3u8) {
        "刷新观看\n地址: " + m3u8;
    } else {
        "获取视频地址失败";
    }
}

