    result.push({
        title: so[0],
        url: "",
        style: { 
            layout_flexGrow: 1, 
            layout_flexBasisPercent: 1 
        }
    });

    // 添加该排序下的所有标签
    tags.forEach(tag => {
        createCategory(tag.text, tag.value, so[1]);
    });
});
JSON.stringify(result);

